import{_ as t,o as a,c as r,ak as n}from"./chunks/framework.B8jO0odJ.js";const h=JSON.parse('{"title":"Chainy quest curriculum and source map","description":"Adopted gameplay sequence: October 23, 2026. This is project design, not school-approved curriculum. Audience: ages 12–17; offline-first Android. GDD v2 owns exact quest behav","frontmatter":{"title":"Chainy quest curriculum and source map","description":"Adopted gameplay sequence: October 23, 2026. This is project design, not school-approved curriculum. Audience: ages 12–17; offline-first Android. GDD v2 owns exact quest behav","source":"docs/planning/quest-curriculum.md","category":"Delivery & team","sourceUpdated":"2026-10-23T16:51:22+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/planning/quest-curriculum.md","filePath":"content/docs/planning/quest-curriculum.md"}'),o={name:"content/docs/planning/quest-curriculum.md"};function s(i,e,c,d,l,u){return a(),r("div",null,[...e[0]||(e[0]=[n('<div><h1 id="chainy-quest-curriculum-and-source-map">Chainy quest curriculum and source map<a class="header-anchor" href="#chainy-quest-curriculum-and-source-map" aria-label="Link to this section">​</a></h1><p>Adopted gameplay sequence: October 23, 2026. This is project design, <strong>not school-approved curriculum</strong>. Audience: ages 12–17; offline-first Android. <a href="/Chainy-Docs/content/docs/game-design.html">GDD v2</a> owns exact quest behavior.</p><p>The supplied <em>Web3 Young Learners Encyclopedia</em> (Cryptita Plays / Bitget) supplies A–Z Web3/blockchain topics, not AI curriculum or validated learning outcomes. Its <a href="/Chainy-Docs/content/docs/archive/source-material/web3-young-learners-encyclopedia-a-z-contents.html">source contents</a> and the <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/docs/planning/quest-curriculum.html">previous quest map</a> preserve the detailed page anchors.</p><h2 id="adopted-sequence">Adopted sequence<a class="header-anchor" href="#adopted-sequence" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Quest / gate</th><th>Observable learner action</th><th>Source anchors and handoff</th></tr></thead><tbody><tr><td>W01 CORE</td><td>Meet Sean; identify a shareable address without exposing secrets</td><td>K/11 keys, W/23 wallets, I/09 safety, Y/25 privacy; safety supplements pp.36–38</td></tr><tr><td>W02 CORE</td><td>Help a resident; receive 12 fictional coins once</td><td>C/03 cryptocurrency, T/20 tokens, F/06 fiat distinction; no real value or profit claim</td></tr><tr><td>W03 CORE</td><td>Review lantern #014 price 8 + fee 1; authorize or cancel; confirm balance 3</td><td>G/07 fees, L/12 ledger, O/15 on/off-chain; simulation only</td></tr><tr><td>W04 CORE</td><td>Inspect ownership, equip without another charge, restore workshop</td><td>N/14 NFT, T/20 tokens; token record does not imply copyright or real-world value</td></tr><tr><td>W05–W08 FULL</td><td>Exchange Builder Tokens, fulfill conditional agreement, rehearse fictional recovery, restore harbor</td><td>E/05 exchange, S/19 contract, K/11 keys, W/23 wallet, R/18 risks; no real secrets, trade or external execution</td></tr><tr><td>B01 CORE</td><td>Meet Matthew; inspect the same lantern purchase</td><td>L/12 ledger, B/02 blockchain</td></tr><tr><td>B02 CORE</td><td>Connect three subsequent blocks to a trusted checkpoint</td><td>B/02; block/immutable glossary p.35; symbolic references are not cryptographic security</td></tr><tr><td>B03 CORE</td><td>Reject altered price 6 using original price 8 evidence</td><td>Ledger consistency and verification; not majority vote or matching for its own sake</td></tr><tr><td>B04–B06 FULL</td><td>Sync a stale node, check candidates, compare nonce-mining and validator roles</td><td>D/04 decentralization, M/13 mining/validators, P/16 proof systems; node/consensus glossary p.35; networks differ</td></tr><tr><td>B07 CORE demo / FULL</td><td>Restore beacon and clearly label demo chapter completion</td><td>Synthesis; demo success does not mean all full-world quests are complete</td></tr><tr><td>A01–A03 STRETCH</td><td>Meet Lee; label Routine/Review examples, train a tiny local classifier, revise using practice cases, test reserved fresh cases</td><td>Use the GDD&#39;s AI references; the encyclopedia contains no AI curriculum. Six/four/four counts and 3-NN are prototype candidates, not validated dataset/model choices.</td></tr><tr><td>A04–A05 FULL</td><td>Verify authored assistant advice; approve/reject supervised dispatch</td><td>Distinguish scripted assistant, trained classifier and rule-driven action; no cloud AI or autonomous real-world action</td></tr></tbody></table><h2 id="learning-and-presentation-rules">Learning and presentation rules<a class="header-anchor" href="#learning-and-presentation-rules" aria-label="Link to this section">​</a></h2><p>Sherwin approves goal, prerequisite, action, reasoning evidence and feedback; Sean authors dialogue, definitions and contextual Quiz explanations; Christian implements logic/data; Miguel implements screens; Luis supplies art.</p><p>Use the same purchase throughout Web3 and Blockchain. Quest states are locked, available, active, ready to report and completed. Retain early pickups and issue rewards once. The quest log is chronological; the encyclopedia uses Discovered / Explained / Practiced / Demonstrated, not an unsupported mastery score.</p><p>All twelve full-design concepts remain: cryptocurrency, blockchain, exchange, gas, keys, mining/validators, NFT, smart contract, token, wallet, seed phrase and node. CORE exposes only the bounded chapter; do not claim every concept has a full hands-on mechanic by November 10.</p><p>Contextual Quiz supports decisions. Standalone Wordle and BlockMatch are deferred; Blockchain repair is a separate mechanic, not a renamed BlockMatch. No real wallet, QR scanning, exchange, secret or payment is involved.</p><h2 id="remaining-decisions">Remaining decisions<a class="header-anchor" href="#remaining-decisions" aria-label="Link to this section">​</a></h2><p>Approve final age-appropriate copy and contextual question rules. Validate the actual save/checkpoint interface. Admit AI only after core Android tests and a capacity check; freeze feature encoding and independent test separation before claiming a trained activity. Confirm adviser requirements separately from the November 10 Cryptita Plays community beta.</p></div>',1)])])}const m=t(o,[["render",s]]);export{h as __pageData,m as default};
